import {comparisonPreview} from './comparison-preview.js';
import {skyMarkup,mountSky} from './sky.js';
import {MIRA_CELL} from './sky-model.js';
import { STATUS, MIRA, regionBounds, cellBounds, regionName, cellName, key, readState, sampleStatus, regionStatus, parseSelection, nextRegion } from './model.js';
import { drawAtlas } from './atlas.js';
const app = document.querySelector('#app');
let state = readState(), animation, reviewTimer, resizeTimer, reviewRun = null, science, epoch = 0;
const arrow = '<span class="arrow" aria-hidden="true">↗</span>';
const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const repeats = (n,fn) => Array.from({length:n},(_,i)=>fn(i)).join('');
const real = (r,c) => r===MIRA.region && c===MIRA.cell;
const urlFor = (r=null,c=null) => '/explore/'+(r===null?'':`?region=${r}`+(c===null?'':`&cell=${c}`));
const shownStatus = (r,c) => reviewRun?.r===r && reviewRun?.c===c ? 'working' : sampleStatus(r,c,state.reviews);
const statusIcon = s => `<span class="status-icon" style="--status:${STATUS[s].color}" aria-hidden="true">${STATUS[s].icon}</span>`;
function save(){try{localStorage.setItem('sate-prototype-v1',JSON.stringify(state));return true;}catch{toast('Browser storage is unavailable. Changes last for this visit.');return false;}}
function toast(text){const t=document.querySelector('#toast');t.textContent=text;t.classList.add('show');clearTimeout(t.timer);t.timer=setTimeout(()=>t.classList.remove('show'),3500);}
function header(path){return `<header class="site-header"><a class="brand" href="/" aria-label="SATE home"><span class="brand-mark" aria-hidden="true">${repeats(9,()=>'<i></i>')}</span>SATE</a><nav class="header-nav" aria-label="Main navigation">${[['/explore/','Explore'],['/contribute/','Contribute'],['/observations/mira/','The first look']].map(([p,n])=>`<a href="${p}" ${path===p?'class="active" aria-current="page"':''}>${n}</a>`).join('')}</nav><div class="header-end"><a class="nav-cta" href="/explore/">Enter the atlas ${arrow}</a></div></header>`;}
function footer(){return `<footer class="site-footer"><a class="footer-brand" href="/">SATE</a><span>SATE helps you explore telescope images and compare observations of the same sky region.</span><div class="footer-links"><a href="/about/">About the prototype</a><a href="/observations/mira/">Data &amp; sources</a></div></footer>`;}
function navigate(url,{replace=false}={}){clearInterval(animation);animation=null;(replace?history.replaceState:history.pushState).call(history,{},'',url);render();window.scrollTo(0,0);}
function landing(){return `<main id="main"><section class="hero hero-photo"><img class="hero-background" src="/assets/carina-nebula-hero.png" alt="" width="1280" height="741" fetchpriority="high"><div class="hero-inner shell"><div class="hero-copy"><h1>Help find objects<br>in space<br><em>and compare</em></h1><p>Explore telescope images, select a region of the sky, and compare observations to see how objects change over time and help find objects.</p><div class="hero-actions"><a class="button lime button-large" href="/explore/">Open sky map ${arrow}</a><a class="button outline button-large" href="/contribute/">Lend computing power ${arrow}</a></div></div></div><a class="hero-image-credit" href="https://science.nasa.gov/asset/webb/cosmic-cliffs-in-the-carina-nebula-nircam-image/" target="_blank" rel="noreferrer">Webb · Cosmic Cliffs<br><span>Image: NASA, ESA, CSA, STScI ↗</span></a></section><div class="shell"><div class="hero-bottom"><span><i class="dot"></i> PUBLIC TELESCOPE DATA</span><span>EXPLORE REGIONS. COMPARE OBSERVATIONS.</span><a href="/about/">ABOUT THIS PROTOTYPE ↗</a></div></div>${comparisonPreview()}<section class="shell participation"><div><h2 class="section-title">Help analyse<br>telescope images.</h2><p class="section-copy">Start with a real observation to see how comparisons work, then choose how you’d like to contribute analysis or computing power.</p><a class="text-link" href="/contribute/">Find your way to help ${arrow}</a></div><div class="participation-list"><a href="/contribute/" class="contribution-line contribution-photo ai-photo"><img class="contribution-image" src="/assets/spherex-orbit-card.jpg" alt="" width="1920" height="1080" loading="lazy"><div><h3>Bring your AI</h3><p>Give an assistant a small investigation. Compare images, check sources, bring back the evidence.</p></div>${arrow}</a><a href="/observations/mira/" class="contribution-line contribution-photo observation-action"><img class="contribution-image" src="/assets/spherex-observation-card.jpg" alt="" width="1024" height="575" loading="lazy"><div><h3>See a real observation</h3><p>Compare real telescope images of the same star, six months apart.</p></div>${arrow}</a><a class="contribution-credits" href="/about/">Images: NASA/JPL-Caltech</a></div></section></main>${footer()}`;}
function contribute(){return `<main id="main" class="contribute-page"><section class="contribute-hero" aria-labelledby="contribute-heading"><img class="contribute-hero-image" src="/assets/spherex-orbit-card.jpg" alt="" width="1920" height="1080" fetchpriority="high"><div class="shell"><div class="page-heading"><h1 id="contribute-heading">Help analyse changes<br>in telescope images.</h1><p>Comparing observations can reveal objects that brighten, fade or move. The aim is to let volunteers help investigate those changes using AI assistants and spare computing power.</p></div></div><a class="contribute-hero-credit" href="https://science.nasa.gov/photojournal/spherex-in-orbit-artists-concept/" target="_blank" rel="noreferrer">SPHEREx · Artist’s concept<br>NASA/JPL-Caltech ↗</a></section><div class="shell contribute-layout"><div class="contribute-explanation"><section aria-labelledby="ai-purpose"><span class="contribute-status">Planned feature</span><h2 id="ai-purpose">Use AI to investigate a sky region</h2><p>An AI assistant could compare images of the same region, check observation dates and source records, and summarise possible changes with supporting evidence. This would help people decide which objects deserve a closer look.</p><p class="contribute-availability">AI assistants cannot be connected here yet, and this page does not use your AI account or allowance.</p></section><section aria-labelledby="compute-purpose"><span class="contribute-status">Planned feature</span><h2 id="compute-purpose">Contribute computing power to image analysis</h2><p>Preparing telescope images for comparison takes processing time. The proposed feature would use spare computing capacity to align images and compare observations across a selected region.</p><p class="contribute-availability">Background computing is not available yet. Visiting this page does not start processing jobs.</p></section></div><aside class="contribute-summary" aria-labelledby="contribute-start"><h2 id="contribute-start">Start with a real observation</h2><p>Open the variable-star example and move the date slider between November 2025 and June 2026. Compare the star’s brightness, then check the source records to see where the images came from.</p><a class="button full-width" href="/observations/mira/">Compare the star images ${arrow}</a><p>To explore further, open the sky map, select a region and use the wavelength slider to view it in different infrared bands.</p><a class="button outline full-width" href="/explore/">Open sky map ${arrow}</a></aside></div></main>${footer()}`;}
function example(){return `<main id="main" class="shell"><div class="page-heading"><div class="eyebrow">A real SPHEREx observation</div><h1>A star, six months apart.</h1><p>Same patch of sky. Same display scale. A known variable star grows fainter.</p></div><div class="example-layout"><div><div class="science-view"><div class="science-frame"><span class="science-field-label">J1502099+593125 · 60 arcsec field</span><div class="science-image-wrap"><img id="science-image" src="/assets/mira-1.png" alt="SPHEREx observation of the known variable, November 2025"><div id="science-labels" class="science-labels"></div></div></div><div class="science-controls"><button class="play-btn" data-action="play" aria-label="Play observations">▶</button><input id="epoch" aria-label="Observation window" type="range" min="0" max="1" step="1" value="0"><span class="science-date" id="science-date">30 Nov 2025</span></div></div><div class="science-under"><label><input type="checkbox" id="catalog-toggle" checked> Known-source markers</label><span>North up · East left</span></div><p class="tiny">○ Gaia &nbsp; ☐ Infrared catalog &nbsp; ◯ Known variable<br>Catalog positions are reference positions; see source details below.</p></div><aside class="science-aside"><div class="aside-top"><span class="label-tag real">Known Mira variable</span><h2>A visible change.</h2><p>This is a known source, showing why comparing observations matters.</p><div class="measurement">≈79%</div><div class="measure-label">Lower measured aperture signal</div><p>June relative to November, in the matched spectral samples.</p></div><dl class="fact-list"><div class="fact-row"><dt>Instrument</dt><dd>SPHEREx</dd></div><div class="fact-row"><dt>Position</dt><dd>225.5413°, +59.5225°</dd></div><div class="fact-row"><dt>First window</dt><dd>30 Nov 2025</dd></div><div class="fact-row"><dt>Second window</dt><dd>9–21 Jun 2026</dd></div><div class="fact-row"><dt>Native pixels</dt><dd>6.15 arcsec</dd></div></dl><a class="button outline full-width" href="/explore/?hpx=${MIRA_CELL}&order=9">Find it in the atlas ${arrow}</a><details class="science-details"><summary>How these images were made</summary><div class="details-content">Two matched spectral samples per window, registered to the same sky coordinates and shown with the same stretch. June combines observations across 12 days. The cutout is resampled; the native resolution is coarser than the displayed pixels. Catalog markers identify known sources, not new discoveries. Asteroid and comet completeness remains unresolved.<p id="source-links">Loading observation records…</p><a href="/assets/mira.json" download="sate-spherex-observation.json">Download provenance JSON ↓</a></div></details></aside></div></main>${footer()}`;}
function about(){return `<main id="main" class="shell"><div class="page-heading"><div class="eyebrow">About SATE</div><h1>A shared search,<br>starting small.</h1><p>Explore the sky. Choose a square. Bring back something worth a closer look.</p></div><div class="legal-content"><h2>This is an early prototype</h2><p>The atlas, cell selection and sample reviews demonstrate the idea. Sample activity is stored only in your browser. No AI allowance is used and no background computation runs.</p><p>The broader aim is to let volunteers contribute bounded investigations and spare computing power to a search for changing and moving objects, including possible distant worlds. A candidate would need independent confirmation.</p><h2>What’s real here</h2><p>The <a href="/observations/mira/">variable-star example</a> uses SPHEREx observations with source records available in the viewer. It is a known Mira variable, J1502099+593125. The example covers a 60-arcsecond field, not an entire atlas cell.</p><p>The interactive atlas uses the <a href="https://irsa.ipac.caltech.edu/data/hips/SPHEREx/spherex_allsky_cube/properties" target="_blank" rel="noreferrer">SPHEREx DR1 all-sky image cube</a>. Its 102 wavelength channels combine observations across time. The equal-area HEALPix grid has 3,145,728 search cells with an equivalent-square width of 6.87 arcminutes. These are investigation areas, not instrument footprints. The homepage background shows Webb’s Cosmic Cliffs in the Carina Nebula, credited to NASA, ESA, CSA and STScI.</p><h2>Reading the colours</h2><p>Grey: not reviewed. Blue: in progress. Green: reviewed with no unexplained candidate in the selected observations. Amber: needs another look. New data can reopen a review. Missing data should never count as a completed search.</p><h2>Your browser, your demo</h2><p>Sample review reports stay in local browser storage. They are not shared with other visitors.</p><button class="button outline small" data-action="reset">Reset my demo activity</button><h2 id="image-credits">Image and data credits</h2><p>The contribution cards use <a href="https://science.nasa.gov/photojournal/spherex-in-orbit-artists-concept/" target="_blank" rel="noreferrer">SPHEREx in Orbit (artist’s concept)</a> and <a href="https://www.nasa.gov/missions/spherex/nasas-spherex-space-telescope-begins-capturing-entire-sky/" target="_blank" rel="noreferrer">a SPHEREx infrared image of stars and dust at 3.29 microns</a>, both credited to NASA/JPL-Caltech. The star-and-dust background illustrates the mission’s observations; the linked comparison shows a separate Mira variable-star field.</p><p>SPHEREx mission data served by NASA/IPAC IRSA. Catalog annotations retain their source IDs in the downloadable observation record. Star-map data: D3-Celestial, © Olaf Frohn and contributors, <a href="/assets/LICENSE">BSD 3-Clause licence</a>.</p></div></main>${footer()}`;}
function paint(){const hero=document.querySelector('#hero-canvas');if(hero)drawAtlas(hero,{polar:true});const sky=document.querySelector('#sky-canvas');if(sky){const{region}=parseSelection(location.search);drawAtlas(sky,region===null?{}:{bounds:regionBounds(region)});}}
async function loadScience(){try{science ||= await fetch('/assets/mira.json').then(r=>{if(!r.ok)throw Error();return r.json();});if(!document.querySelector('#science-image'))return;setEpoch(0);document.querySelector('#source-links').innerHTML=science.observations.map((o,i)=>`<a href="${esc(o.url)}" target="_blank" rel="noreferrer">Observation ${i+1}</a> · ${esc(o.date_avg_utc.slice(0,10))} · ${Number(o.wcs_wave_approx_um).toFixed(3)} µm`).join('<br>');}catch{const t=document.querySelector('#source-links');if(t)t.textContent='Observation records could not be loaded. Please reload.';}}
function setEpoch(n){epoch=Number(n);const img=document.querySelector('#science-image');if(!img)return;img.src=`/assets/mira-${epoch+1}.png`;img.alt=`SPHEREx observation of known variable, ${science?.dates[epoch]||['November 2025','June 2026'][epoch]}`;document.querySelector('#epoch').value=epoch;document.querySelector('#science-date').textContent=science?.dates[epoch]||['30 Nov 2025','9–21 Jun 2026'][epoch];document.querySelector('#science-labels').innerHTML=(science?.catalogs[epoch]||[]).map(s=>`<i class="catalog-dot ${s.catalog.includes('SIMBAD')?'known':s.catalog.includes('Gaia')?'':'infrared'}" style="left:${s.x}%;top:${s.y}%" title="${esc(s.catalog+': '+s.id)}"></i>`).join('');}
let skyCleanup,renderToken=0;
function render(){const token=++renderToken;skyCleanup?.();skyCleanup=null;let path=location.pathname.replace(/\/+$/,'')+'/';if(path==='//')path='/';if(path==='/explore/'&&(new URLSearchParams(location.search).has('assign')||new URLSearchParams(location.search).has('region'))){history.replaceState({},'','/explore/?hpx='+MIRA_CELL+'&order=9');}document.body.classList.toggle('explorer-page',path==='/explore/');const pages={'/':landing,'/explore/':skyMarkup,'/contribute/':contribute,'/observations/mira/':example,'/about/':about};app.innerHTML=header(path)+(pages[path]?pages[path]():`<main id="main" class="not-found"><h1>A little off course.</h1><a class="button" href="/">Return home ${arrow}</a></main>`);document.title=({'/':'Explore and compare space observations','/explore/':'Sky atlas','/contribute/':'Contribute','/observations/mira/':'A star, six months apart','/about/':'About this prototype'}[path]||'Not found')+' — SATE';paint();if(path==='/explore/')mountSky().then(clean=>{if(token===renderToken)skyCleanup=clean;else clean?.();});if(path==='/observations/mira/')loadScience();}
app.addEventListener('click',async e=>{const link=e.target.closest('a');if(link){if(link.hasAttribute('download')||link.target||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;const u=new URL(link.href);if(u.origin===location.origin&&!u.pathname.startsWith('/assets/')){if(location.pathname.startsWith('/explore')||u.pathname.startsWith('/explore'))return;e.preventDefault();navigate(u.pathname+u.search+u.hash);}return;}const button=e.target.closest('button');if(!button||button.closest('[data-sky]'))return;if(button.dataset.selectRegion!==undefined){navigate('/explore/?inspect='+Number(button.dataset.selectRegion));return;}if(button.dataset.region!==undefined){navigate(urlFor(Number(button.dataset.region)));return;}if(button.dataset.cell!==undefined){const{region}=parseSelection(location.search);navigate(urlFor(region,Number(button.dataset.cell)));return;}switch(button.dataset.action){case'all':navigate(urlFor());break;case'example-cell':navigate('/explore/?inspect='+MIRA.region);break;case'auto':{const n=nextRegion(state.reviews);if(n)navigate(urlFor(n.region,n.cell));else toast('All demo cells have been assigned. Reset the demo to start again.');break;}case'cancel':clearInterval(reviewTimer);reviewRun=null;render();break;case'copy':try{await navigator.clipboard.writeText(location.href);toast('Cell link copied.');}catch{toast('Copy the cell URL from your address bar.');}break;case'play':if(animation){clearInterval(animation);animation=null;button.textContent='▶';button.setAttribute('aria-label','Play observations');}else{animation=setInterval(()=>setEpoch(1-epoch),1000);button.textContent='Ⅱ';button.setAttribute('aria-label','Pause observations');}break;case'reset':localStorage.removeItem('sate-healpix-reviews-v1');clearInterval(reviewTimer);reviewRun=null;state={reviews:{},preferences:{ai:true,compute:false,batch:'5',power:'light'}};save();toast('Demo activity reset.');break;}});
app.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);if(e.target.id==='coordinate-form'){const ra=Number(f.get('ra')),dec=Number(f.get('dec'));if(!Number.isFinite(ra)||ra<0||ra>=360||!Number.isFinite(dec)||dec< -90||dec>90){document.querySelector('#coord-error').textContent='Use RA 0–360° and Dec −90–90°.';return;}const col=Math.min(11,Math.floor((360-ra)/30)),row=Math.min(5,Math.floor((90-dec)/30)),r=row*12+col,b=regionBounds(r),c=Math.min(2,Math.floor((b.north-dec)/10))*3+Math.min(2,Math.floor((b.west-ra)/10));navigate(urlFor(r,c));}});
app.addEventListener('input',e=>{if(e.target.id==='epoch')setEpoch(e.target.value);if(e.target.id==='catalog-toggle')document.querySelector('#science-labels').hidden=!e.target.checked;});
app.addEventListener('keydown',e=>{const b=e.target.closest('.map-cell,.nine-grid button');if(!b||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;const list=[...b.parentNode.children],cols=b.parentNode.classList.contains('subgrid')||b.parentNode.classList.contains('nine-grid')?3:12,index=list.indexOf(b),move={ArrowLeft:-1,ArrowRight:1,ArrowUp:-cols,ArrowDown:cols}[e.key];e.preventDefault();const next=list[Math.max(0,Math.min(list.length-1,index+move))];b.tabIndex=-1;next.tabIndex=0;next.focus();});
window.addEventListener('popstate',()=>{clearInterval(animation);animation=null;render();});window.addEventListener('resize',()=>{clearTimeout(resizeTimer);resizeTimer=setTimeout(paint,120);});render();
